	'Falta la URL del CRM.' => 'Falta l\'URL del CRM.',
	'Faltan el usuario o la contraseña del CRM de este grupo (o no se puede descifrar la contraseña guardada).' => 'Falten l\'usuari o la contrasenya del CRM d\'aquest grup (o no es pot desxifrar la contrasenya desada).',
