	// Domiciliaciones SEPA
	'Como parte de sus derechos, el deudor está legitimado al reembolso por su entidad en los términos y condiciones del contrato suscrito con la misma. La solicitud de reembolso deberá efectuarse dentro de las ocho semanas que siguen a la fecha de adeudo en cuenta. Puede obtener información adicional sobre sus derechos en su entidad financiera.' => 'Com a part dels seus drets, el deutor està legitimat per al reembossament per part de la seva entitat en els termes i condicions del contracte subscrit amb aquesta. La sol·licitud de reembossament s\'haurà d\'efectuar dins de les vuit setmanes següents a la data de càrrec en compte. Pot obtenir informació addicional sobre els seus drets a la seva entitat financera.',
	'El BIC no es válido (8 u 11 caracteres). Puedes dejarlo vacío.' => 'El BIC no és vàlid (8 o 11 caràcters). Pots deixar-lo buit.',
	'El IBAN debe empezar por dos letras del país y dos cifras de control (por ejemplo ES91…).' => 'L\'IBAN ha de començar per dues lletres del país i dues xifres de control (per exemple ES91…).',
	'El IBAN no es de un país de la zona SEPA.' => 'L\'IBAN no és d\'un país de la zona SEPA.',
	'El deudor puede anular esta autorización cuando quiera desde «Mis pagos» o avisando a la Tesorería del grupo.' => 'El deutor pot anul·lar aquesta autorització quan vulgui des de «Els meus pagaments» o avisant la Tresoreria del grup.',
	'El identificador del acreedor no tiene el formato correcto (en España, ES + 2 cifras de control + 3 caracteres + NIF: 16 caracteres, p. ej. ES12ZZZG12345678).' => 'L\'identificador del creditor no té el format correcte (a Espanya, ES + 2 xifres de control + 3 caràcters + NIF: 16 caràcters, p. ex. ES12ZZZG12345678).',
	'El servidor de correo no ha aceptado el email.' => 'El servidor de correu no ha acceptat l\'email.',
	'Elige la fecha de cobro.' => 'Tria la data de cobrament.',
	'Enviada al banco' => 'Enviada al banc',
	'Error desconocido' => 'Error desconegut',
	'Escribe el IBAN.' => 'Escriu l\'IBAN.',
	'Escribe el nombre y los apellidos del titular de la cuenta.' => 'Escriu el nom i els cognoms del titular del compte.',
	'Escribe la dirección del titular (calle, código postal y población).' => 'Escriu l\'adreça del titular (carrer, codi postal i població).',
	'Esta autorización sirve para cobrar la cuota y otros pagos del grupo (por ejemplo, las cuotas de cada ronda). Tipo de pago: recurrente. %s comunicará al deudor la fecha y el importe de cada adeudo con al menos %d días de antelación (por email y en «Mis pagos»).' => 'Aquesta autorització serveix per cobrar la quota i altres pagaments del grup (per exemple, les quotes de cada ronda). Tipus de pagament: recurrent. %s comunicarà al deutor la data i l\'import de cada càrrec amb almenys %d dies d\'antelació (per email i a «Els meus pagaments»).',
	'Falta el identificador del acreedor (ICS). Lo da el banco al contratar las domiciliaciones.' => 'Falta l\'identificador del creditor (ICS). El dona el banc en contractar les domiciliacions.',
	'Falta el nombre del acreedor (el del grupo o la asociación que cobra).' => 'Falta el nom del creditor (el del grup o l\'associació que cobra).',
	'Faltan datos del acreedor: complétalos en «Datos del acreedor».' => 'Falten dades del creditor: completa-les a «Dades del creditor».',
	'Familia %s: %s' => 'Família %s: %s',
	'Familia %s: el IBAN de la autorización no es válido (o ya no se conserva).' => 'Família %s: l\'IBAN de l\'autorització no és vàlid (o ja no es conserva).',
	'Familia %s: el importe debe ser mayor que 0.' => 'Família %s: l\'import ha de ser major que 0.',
	'Familia %s: falta el nombre del titular.' => 'Família %s: falta el nom del titular.',
	'Familia %s: tipo de secuencia no válido.' => 'Família %s: tipus de seqüència no vàlid.',
	'Generada' => 'Generada',
	'Hemos guardado tu autorización de domiciliación SEPA' => 'Hem desat la teva autorització de domiciliació SEPA',
	'IBAN del acreedor: ' => 'IBAN del creditor: ',
	'La autorización tiene que firmarla tu madre, padre o tutor/a desde su cuenta: por ser menor de edad no puedes firmarla tú.' => 'L\'autorització l\'ha de signar la teva mare, pare o tutor/a des del seu compte: com que ets menor d\'edat no la pots signar tu.',
	'La cuenta no tiene un email al que escribir.' => 'El compte no té cap email al qual escriure.',
	'La fecha de cobro no es válida.' => 'La data de cobrament no és vàlida.',
	'La fecha de cobro tiene que ser un día laborable (de lunes a viernes).' => 'La data de cobrament ha de ser un dia laborable (de dilluns a divendres).',
	'La fecha de cobro tiene que ser, como pronto, el %s (%d días hábiles desde hoy): los bancos necesitan ese margen.' => 'La data de cobrament ha de ser, com a molt aviat, el %s (%d dies hàbils des d\'avui): els bancs necessiten aquest marge.',
	'La fecha del cobro no es válida (no puede ser posterior a hoy).' => 'La data del cobrament no és vàlida (no pot ser posterior a avui).',
	'Los cobros solo se registran de una remesa enviada al banco.' => 'Els cobraments només es registren d\'una remesa enviada al banc.',
	'Los datos de esta remesa ya no se conservan.' => 'Les dades d\'aquesta remesa ja no es conserven.',
	'Los dígitos de control del IBAN no cuadran: revisa que esté bien escrito.' => 'Els dígits de control de l\'IBAN no quadren: revisa que estigui ben escrit.',
	'Mediante la firma de esta orden de domiciliación, el deudor autoriza (A) a %s a enviar instrucciones a la entidad del deudor para adeudar su cuenta y (B) a la entidad para efectuar los adeudos en su cuenta siguiendo las instrucciones de %s.' => 'Mitjançant la signatura d\'aquesta ordre de domiciliació, el deutor autoritza (A) %s a enviar instruccions a l\'entitat del deutor per carregar el seu compte i (B) l\'entitat a efectuar els càrrecs al seu compte seguint les instruccions de %s.',
	'No hay ningún adeudo que incluir.' => 'No hi ha cap càrrec que incloure.',
	'No se ha podido guardar la autorización. Inténtalo de nuevo.' => 'No s\'ha pogut desar l\'autorització. Torna-ho a provar.',
	'No se ha podido guardar la remesa. Inténtalo de nuevo.' => 'No s\'ha pogut desar la remesa. Torna-ho a provar.',
	'No se puede leer la autorización (pídele que la firme de nuevo)' => 'No es pot llegir l\'autorització (demana-li que la signi de nou)',
	'Sin autorización SEPA' => 'Sense autorització SEPA',
	'Todas esas familias ya están en otra remesa que aún no tiene registrados sus cobros.' => 'Totes aquestes famílies ja són en una altra remesa que encara no té registrats els cobraments.',
	'Todo lo pendiente' => 'Tot el que està pendent',
	'Tu cuenta no puede firmar autorizaciones de domiciliación.' => 'El teu compte no pot signar autoritzacions de domiciliació.',
	'Un IBAN de %s tiene %d caracteres y este tiene %d.' => 'Un IBAN de %s té %d caràcters i aquest en té %d.',
	'Ya está en la remesa %s (falta registrar su cobro)' => 'Ja és a la remesa %s (falta registrar-ne el cobrament)',
	'[%s] Aviso de cargo el %s' => '[%s] Avís de càrrec el %s',

	// Emails
	'%1$s te ha dado acceso al área privada del %2$s como <strong>%3$s</strong>.' => '%1$s t\'ha donat accés a l\'àrea privada del %2$s com a <strong>%3$s</strong>.',
