	'Desde ahora la cuenta <strong>%s</strong> entra con esta dirección de email (o con ese usuario).' => 'A partir d\'ara el compte <strong>%s</strong> entra amb aquesta adreça d\'email (o amb aquest usuari).',
	'Domiciliación SEPA' => 'Domiciliació SEPA',
