	'Elegir contraseña nueva' => 'Tria una contrasenya nova',
	'Es un adeudo directo SEPA, con la autorización que firmaste (referencia %s). Puedes ver el cargo y tus pagos en «Mis pagos». Si no estás de acuerdo, avísanos antes de esa fecha.' => 'És un càrrec directe SEPA, amb l\'autorització que vas signar (referència %s). Pots veure el càrrec i els teus pagaments a «Els meus pagaments». Si no hi estàs d\'acord, avisa\'ns abans d\'aquesta data.',
	'Escribe a %s, con el nombre del socio/a y tu relación con él o ella (madre, padre, tutor/a o el propio socio/a).' => 'Escriu a %s, amb el nom del soci/sòcia i la teva relació amb ell o ella (mare, pare, tutor/a o el mateix soci/sòcia).',
	'Habla con la Secretaría de tu grupo, diciéndole el nombre del socio/a y tu relación con él o ella (madre, padre, tutor/a o el propio socio/a).' => 'Parla amb la Secretaria del teu grup, dient-li el nom del soci/sòcia i la teva relació amb ell o ella (mare, pare, tutor/a o el mateix soci/sòcia).',
	'Hemos comprobado tu solicitud de acceso y ya está aprobada. Desde el área privada podrás consultar y mantener al día tus datos y los de tu familia.' => 'Hem comprovat la teva sol·licitud d\'accés i ja està aprovada. Des de l\'àrea privada podràs consultar i mantenir al dia les teves dades i les de la teva família.',
	'Hemos comprobado tu solicitud de acceso y ya está aprobada. Desde el área privada podrás consultar y mantener al día tus datos.' => 'Hem comprovat la teva sol·licitud d\'accés i ja està aprovada. Des de l\'àrea privada podràs consultar i mantenir al dia les teves dades.',
	'Hemos guardado tu <strong>autorización de domiciliación SEPA</strong> para los pagos del %s.' => 'Hem desat la teva <strong>autorització de domiciliació SEPA</strong> per als pagaments del %s.',
	'Hemos recibido una petición para elegir una contraseña nueva para el usuario <strong>%s</strong> (con el que también puedes entrar usando esta dirección de email).' => 'Hem rebut una petició per triar una contrasenya nova per a l\'usuari <strong>%s</strong> (amb el qual també pots entrar fent servir aquesta adreça d\'email).',
	'Hemos revisado tu solicitud de acceso al área privada del <strong>%s</strong> y, con los datos que nos has enviado, <strong>no hemos podido darte acceso</strong>.' => 'Hem revisat la teva sol·licitud d\'accés a l\'àrea privada del <strong>%s</strong> i, amb les dades que ens has enviat, <strong>no hem pogut donar-te accés</strong>.',
	'Hola, %s:' => 'Hola, %s:',
