	'Se te ha dado acceso al área privada del %1$s como <strong>%2$s</strong>.' => 'T\'han donat accés a l\'àrea privada del %1$s com a <strong>%2$s</strong>.',
	'Se te ha dado acceso al área privada del %s.' => 'T\'han donat accés a l\'àrea privada del %s.',
	'Si el botón no funciona, copia esta dirección en tu navegador:' => 'Si el botó no funciona, copia aquesta adreça al teu navegador:',
	'Si no esperabas este correo, puedes ignorarlo.' => 'Si no esperaves aquest correu, pots ignorar-lo.',
	'Si no has pedido tú este acceso, puedes ignorar este correo.' => 'Si no has demanat tu aquest accés, pots ignorar aquest correu.',
	'Suele ser porque algún dato no coincide con la ficha del socio/a o porque la ficha no está al día. Si crees que es un error, o quieres volver a intentarlo, ponte en contacto con nosotros:' => 'Normalment és perquè alguna dada no coincideix amb la fitxa del soci/sòcia o perquè la fitxa no està al dia. Si creus que és un error, o vols tornar-ho a provar, posa\'t en contacte amb nosaltres:',
	'También puedes entrar escribiendo esta dirección de email en lugar del usuario.' => 'També pots entrar escrivint aquesta adreça d\'email en lloc de l\'usuari.',
	'Te avisamos de que <strong>%1$s</strong> se cargarán <strong>%2$s</strong> en la cuenta <strong>%3$s</strong>, en concepto de «%4$s».' => 'T\'avisem que es carregaran <strong>%1$s</strong> <strong>%2$s</strong> al compte <strong>%3$s</strong>, en concepte de «%4$s».',
	'Te avisaremos antes de cada cargo, con su fecha y su importe. Puedes ver la autorización, imprimirla o anularla cuando quieras desde «Mis pagos».' => 'T\'avisarem abans de cada càrrec, amb la seva data i el seu import. Pots veure l\'autorització, imprimir-la o anul·lar-la quan vulguis des de «Els meus pagaments».',
