	'En cada número repetido lo conservará quien entra en la web con él (o quien tiene membresía activa, o el nº de Scouts de España más antiguo); el resto recibirá el siguiente número libre, guardado en el CRM. Se hace en segundo plano. ¿Continuar?' => 'En cada número repetit el conservarà qui entra al web amb ell (o qui té membresia activa, o el núm. de Scouts de España més antic); la resta rebrà el següent número lliure, desat al CRM. Es fa en segon pla. Vols continuar?',
