	'Otra ficha de tu grupo ya tiene este documento (%s): sería la misma persona dos veces. Revísalo antes de seguir.' => 'Una altra fitxa del teu grup ja té aquest document (%s): seria la mateixa persona dues vegades. Revisa-ho abans de continuar.',
	'Para cambiar de sección tiene que tener una membresía activa (y solo una).' => 'Per canviar de secció ha de tenir una membresia activa (i només una).',
	'Se ha quedado a medias. Vuelve a intentarlo: seguirá donde se quedó, sin crear otra ficha. Motivo: ' => 'S\'ha quedat a mitges. Torna-ho a provar: continuarà on es va quedar, sense crear una altra fitxa. Motiu: ',
	'Ya está en esa sección.' => 'Ja és en aquesta secció.',
	'Ya hay un alta en curso para esta persona. Espera a que termine.' => 'Ja hi ha una alta en curs per a aquesta persona. Espera que acabi.',
	'Ya tiene ficha en tu grupo: no se crea otra. Si no tiene membresía activa, dale una nueva en su ficha.' => 'Ja té fitxa al teu grup: no se\'n crea una altra. Si no té membresia activa, dona-li\'n una de nova a la seva fitxa.',
	'Ya tiene una membresía activa. Para pasarla a otra sección, usa «Cambiar de sección».' => 'Ja té una membresia activa. Per passar-la a una altra secció, fes servir «Canviar de secció».',

