	'Las cuentas familiares que la representan (%s) dejarán de verla; si no representan a nadie más con membresía activa, tampoco podrán entrar.' => 'Els comptes familiars que la representen (%s) deixaran de veure-la; si no representen ningú més amb membresia activa, tampoc no podran entrar.',
	'Membresía activa:' => 'Membresia activa:',
	'Membresía en el CRM' => 'Membresia al CRM',
	'Membresía que se cierra' => 'Membresia que es tanca',
	'Membresías que se cierran' => 'Membresies que es tanquen',
	'No se borra nada: la ficha y sus membresías anteriores se quedan en el CRM. Si vuelve, se le da una membresía nueva.' => 'No s\'esborra res: la fitxa i les seves membresies anteriors es queden al CRM. Si torna, se li dona una membresia nova.',
	'Nueva membresía' => 'Membresia nova',
	'Para quien aún no lo tenía (por ejemplo, un menor que lo acaba de sacar). Antes de guardarlo se comprueba si ya está en otra ficha de tu grupo o en otro grupo u organización de Scouts de España.' => 'Per a qui encara no el tenia (per exemple, un menor que l\'acaba de treure). Abans de desar-lo es comprova si ja és en una altra fitxa del teu grup o en un altre grup o organització de Scouts de España.',
	'Para quien vuelve al grupo: la membresía nueva va en su ficha de siempre, con su mismo nº de socio/a. No se crea otra ficha.' => 'Per a qui torna al grup: la membresia nova va a la seva fitxa de sempre, amb el mateix número de soci/sòcia. No es crea cap altra fitxa.',
	'Poner el documento' => 'Posa el document',
	'Qué cambia con la baja:' => 'Què canvia amb la baixa:',
