	'Deja de contar en la cuota de la familia nº %s: Tesorería lo verá en «Bajas recientes».' => 'Deixa de comptar en la quota de la família núm. %s: Tresoreria ho veurà a «Baixes recents».',
	'Documento guardado en la ficha de %s.' => 'Document desat a la fitxa de %s.',
	'El usuario del CRM de tu grupo no tiene permiso para crear personas y membresías. Un administrador puede revisarlo en wp-admin → Grupos Scouts.' => 'L\'usuari del CRM del teu grup no té permís per crear persones i membresies. Un administrador ho pot revisar a wp-admin → Grupos Scouts.',
