	'Las cuentas familiares que la representan ya no la ven; si no representan a nadie más con membresía activa, tampoco pueden entrar.' => 'Els comptes familiars que la representen ja no la veuen; si no representen ningú més amb membresia activa, tampoc no poden entrar.',
