	'Empieza por su documento: se comprueba si ya tiene ficha, en tu grupo o en otro grupo u organización de Scouts de España.' => 'Comença pel seu document: es comprova si ja té fitxa, al teu grup o en un altre grup o organització de Scouts de España.',
