	// Altas en el CRM · tutores y aviso de baja por email (v0.23.1, doc 34)
	'Por debajo de %d años hace falta el tutor/a 1: nombre, apellidos y email.' => 'Per sota de %d anys cal el tutor/a 1: nom, cognoms i email.',
	'Desde ese día ya no cuenta como socio/a del grupo ni en las cuotas, y su acceso al área privada se cierra. Su ficha se conserva: si algún día vuelve, solo hay que darle de alta de nuevo.' => 'Des d\'aquell dia ja no compta com a soci/sòcia del grup ni en les quotes, i el seu accés a l\'àrea privada es tanca. La seva fitxa es conserva: si algun dia torna, només cal donar-la d\'alta de nou.',
	'Es de la familia <strong>%s</strong>: desde la baja ya no cuenta en su cuota. Revisa si hay que ajustar algo en sus pagos.' => 'És de la família <strong>%s</strong>: des de la baixa ja no compta en la seva quota. Revisa si cal ajustar alguna cosa en els seus pagaments.',
	'Ir a Tesorería' => 'Ves a Tresoreria',
	'Motivo:' => 'Motiu:',
	'No está en ninguna familia de Tesorería.' => 'No és en cap família de Tresoreria.',
	'Se ha dado de baja en el CRM a <strong>%1$s</strong> (nº de socio/a %2$s) desde el <strong>%3$s</strong>.' => 'S\'ha donat de baixa al CRM <strong>%1$s</strong> (núm. de soci/sòcia %2$s) des del <strong>%3$s</strong>.',
	'Si es un error o tienes cualquier duda, escríbenos a %s.' => 'Si és un error o tens qualsevol dubte, escriu-nos a %s.',
	'Si es un error o tienes cualquier duda, habla con la Secretaría del grupo.' => 'Si és un error o tens qualsevol dubte, parla amb la Secretaria del grup.',
	'Te confirmamos que <strong>%1$s</strong> ha causado baja en el <strong>%2$s</strong> el %3$s.' => 'Et confirmem que <strong>%1$s</strong> ha causat baixa al <strong>%2$s</strong> el %3$s.',
	'Te llega porque tienes la responsabilidad de Tesorería en el área privada del grupo. Para verlo tendrás que iniciar sesión.' => 'T\'arriba perquè tens la responsabilitat de Tresoreria a l\'àrea privada del grup. Per veure-ho hauràs d\'iniciar la sessió.',
	'¡Gracias por todo lo compartido!' => 'Gràcies per tot el que hem compartit!',
	'Se avisa por email a Tesorería y a la familia (o a la propia persona, si es mayor de edad). Con el motivo «Fallecimiento» no se escribe a la familia.' => 'S\'avisa per email Tresoreria i la família (o la mateixa persona, si és major d\'edat). Amb el motiu «Defunció» no s\'escriu a la família.',
	'%d no se han podido enviar (mira Usuarios → Emails).' => '%d no s\'han pogut enviar (mira Usuaris → Emails).',
