	'Las camisas del uniforme necesitan el modelo (chico o chica) y una talla de ese modelo.' => 'Les camises de l\'uniforme necessiten el model (noi o noia) i una talla d\'aquest model.',
	'Modelo (camisas)' => 'Model (camises)',
	'Solo para el tipo «Camisa uniforme»: la gestión de uniformes asigna estas camisas a los pedidos y las descuenta de aquí. Si no escribes la descripción, se pone sola.' => 'Només per al tipus «Camisa uniforme»: la gestió d\'uniformes assigna aquestes camises a les comandes i les descompta d\'aquí. Si no escrius la descripció, es posa sola.',
	'Talla (camisas)' => 'Talla (camises)',
	'chica' => 'noia',
	'%d cambio aprobado y guardado en el CRM.' => '%d canvi aprovat i desat al CRM.',
	'%d cambio no se ha aplicado: el dato del CRM ha cambiado desde que se propuso. Revísalo y márcalo otra vez si quieres aplicarlo igualmente.' => '%d canvi no s\'ha aplicat: la dada del CRM ha canviat des que es va proposar. Revisa-ho i marca\'l una altra vegada si vols aplicar-lo igualment.',
	'%d cambio rechazado. Quien lo propuso verá el motivo en la ficha.' => '%d canvi rebutjat. Qui el va proposar veurà el motiu a la fitxa.',
	'%d cambios aprobados y guardados en el CRM.' => '%d canvis aprovats i desats al CRM.',
	'%d cambios no se han aplicado: el dato del CRM ha cambiado desde que se propusieron. Revísalos y márcalos otra vez si quieres aplicarlos igualmente.' => '%d canvis no s\'han aplicat: la dada del CRM ha canviat des que es van proposar. Revisa\'ls i marca\'ls una altra vegada si vols aplicar-los igualment.',
	'%d cambios rechazados. Quien los propuso verá el motivo en la ficha.' => '%d canvis rebutjats. Qui els va proposar veurà el motiu a la fitxa.',
	'Marca los cambios que quieres aprobar o rechazar.' => 'Marca els canvis que vols aprovar o rebutjar.',
	'No puedes revisar los cambios de esa persona.' => 'No pots revisar els canvis d\'aquesta persona.',
	'Contraer o expandir «%s»' => 'Plega o desplega «%s»',
	'Versión para imprimir' => 'Versió per imprimir',
	'%1$d con membresía activa · %2$d sin membresía activa' => '%1$d amb membresia activa · %2$d sense membresia activa',
	'Del inventario del grupo' => 'De l\'inventari del grup',
	'chico' => 'noi',

	// v0.29: informe «Fichas reducidas» (una ficha por página)
	'Fichas reducidas' => 'Fitxes reduïdes',
	'Las del informe' => 'Les de l\'informe',
	'Presentación' => 'Presentació',
	'Tabla' => 'Taula',
	'Una ficha por persona (al imprimir, una por página)' => 'Una fitxa per persona (en imprimir, una per pàgina)',

	// v0.29: primera camisa de scouter gratis
	'Sin coste: primera camisa de scouter' => 'Sense cost: primera camisa de scouter',

	// v0.29: respuestas del usuario
	'Una página por socio/a con su móvil, su tutor/a y su móvil, la cesión de imagen, las alergias, la alimentación y las enfermedades. Elige la sección al verlo.' => 'Una pàgina per soci/sòcia amb el mòbil, el tutor/a i el seu mòbil, la cessió d\'imatge, les al·lèrgies, l\'alimentació i les malalties. Tria la secció en veure\'l.',
	'Eliminar un pago o un ajuste lo hace Tesorería.' => 'Eliminar un pagament o un ajust ho fa Tresoreria.',

	// v0.30: inventario (material nuevo, comprada, email de revisión, importar repetidos) y uniforme para la sección
	'Cuando hayas comprado el material, márcala como comprada en el área privada: lo comprado se sumará al inventario.' => 'Quan hagis comprat el material, marca-la com a comprada a l\'àrea privada: el que s\'hagi comprat se sumarà a l\'inventari.',
	'La ha revisado %s.' => 'L\'ha revisada %s.',
	'Material nuevo (no está en el inventario)' => 'Material nou (no és a l\'inventari)',
	'Si hace falta, prepara otra lista con los cambios.' => 'Si cal, prepara una altra llista amb els canvis.',
	'Te llega porque pediste esta lista de compra en el área privada del grupo. Para verla tendrás que iniciar sesión.' => 'T\'arriba perquè vas demanar aquesta llista de compra a l\'àrea privada del grup. Per veure-la hauràs d\'iniciar la sessió.',
	'Tesorería <strong>no ha dado el visto bueno</strong> a tu lista de compra de material <strong>%s</strong>: la ha rechazado.' => 'Tresoreria <strong>no ha donat el vistiplau</strong> a la teva llista de compra de material <strong>%s</strong>: l\'ha rebutjada.',
	'Tesorería ha dado el <strong>visto bueno</strong> a tu lista de compra de material <strong>%s</strong>. Ya la puedes descargar en PDF para imprimirla.' => 'Tresoreria ha donat el <strong>vistiplau</strong> a la teva llista de compra de material <strong>%s</strong>. Ja la pots descarregar en PDF per imprimir-la.',
	'Ver la lista' => 'Mostra la llista',
	'Añadir otra línea' => 'Afegeix una altra línia',
	'Comprada' => 'Comprada',
	'Comprada: la marcó %1$s el %2$s. Lo comprado se sumó al inventario.' => 'Comprada: la va marcar %1$s el %2$s. El que es va comprar es va sumar a l\'inventari.',
	'Cuando el material de la lista esté comprado, márcala como comprada: las cantidades se sumarán al inventario y el material nuevo se dará de alta. No se puede deshacer.' => 'Quan el material de la llista estigui comprat, marca-la com a comprada: les quantitats se sumaran a l\'inventari i el material nou es donarà d\'alta. No es pot desfer.',
	'Dado de alta en el inventario' => 'Donat d\'alta a l\'inventari',
	'Escribe qué material nuevo hay que comprar en la línea %d (o deja en blanco su precio).' => 'Escriu quin material nou cal comprar a la línia %d (o deixa en blanc el preu).',
	'Esta lista no se puede marcar como comprada: tiene que tener el visto bueno de Tesorería y no estar ya comprada.' => 'Aquesta llista no es pot marcar com a comprada: ha de tenir el vistiplau de Tresoreria i no estar ja comprada.',
	'Lista %s marcada como comprada.' => 'Llista %s marcada com a comprada.',
	'Lista de material nuevo' => 'Llista de material nou',
	'Marca el material que hay que comprar (lo que todavía no está en el inventario lo podrás escribir en la lista). Si de alguno ya hay %d unidades o más, te preguntaremos si de verdad hace falta comprar más. La lista la tiene que aprobar Tesorería antes de imprimirla.' => 'Marca el material que cal comprar (el que encara no és a l\'inventari el podràs escriure a la llista). Si d\'algun ja n\'hi ha %d unitats o més, et preguntarem si de debò cal comprar-ne més. La llista l\'ha d\'aprovar Tresoreria abans d\'imprimir-la.',
	'Marcar como comprada' => 'Marca com a comprada',
	'Material nuevo' => 'Material nou',
	'Material nuevo, línea %d' => 'Material nou, línia %d',
	'No has marcado ningún material del inventario. Puedes preparar la lista solo con material nuevo (aquí debajo) o volver al inventario y marcar lo que hay que comprar.' => 'No has marcat cap material de l\'inventari. Pots preparar la llista només amb material nou (aquí sota) o tornar a l\'inventari i marcar el que cal comprar.',
	'No se ha podido enviar el email a quien la pidió: díselo tú.' => 'No s\'ha pogut enviar l\'email a qui la va demanar: digues-l\'hi tu.',
	'Ojo: ya hay %d unidad en el inventario. ¿Seguro que hace falta comprar más?' => 'Compte: a l\'inventari ja hi ha %d unitat. Segur que cal comprar-ne més?',
	'Ojo: ya hay %d unidades en el inventario. ¿Seguro que hace falta comprar más?' => 'Compte: a l\'inventari ja hi ha %d unitats. Segur que cal comprar-ne més?',
	'Precio estimado, línea %d (opcional)' => 'Preu estimat, línia %d (opcional)',
	'Quien la pidió no tiene email en el área privada: díselo tú.' => 'Qui la va demanar no té email a l\'àrea privada: digues-l\'hi tu.',
	'Qué hay que comprar' => 'Què cal comprar',
	'Se ha avisado por email a quien la pidió.' => 'S\'ha avisat per email qui la va demanar.',
	'Se ha dado de alta %d material nuevo.' => 'S\'ha donat d\'alta %d material nou.',
	'Se ha sumado lo comprado a %d material del inventario.' => 'S\'ha sumat el que s\'ha comprat a %d material de l\'inventari.',
	'Se ha sumado lo comprado a %d materiales del inventario.' => 'S\'ha sumat el que s\'ha comprat a %d materials de l\'inventari.',
	'Se han dado de alta %d materiales nuevos.' => 'S\'han donat d\'alta %d materials nous.',
	'Se preparan marcando el material en el inventario (y escribiendo el que todavía no está). Tesorería recibe un email y le da el visto bueno; solo entonces se puede descargar el PDF para imprimirla. Quien la pidió recibe un email con la respuesta. Cuando el material esté comprado, se marca la lista como comprada y lo comprado se suma al inventario.' => 'Es preparen marcant el material a l\'inventari (i escrivint el que encara no hi és). Tresoreria rep un email i li dona el vistiplau; només llavors es pot descarregar el PDF per imprimir-la. Qui la va demanar rep un email amb la resposta. Quan el material estigui comprat, es marca la llista com a comprada i el que s\'ha comprat se suma a l\'inventari.',
	'Si hay que comprar algo que todavía no está en el inventario, escríbelo aquí. Cuando la lista se marque como comprada, se dará de alta en el inventario.' => 'Si cal comprar alguna cosa que encara no és a l\'inventari, escriu-la aquí. Quan la llista es marqui com a comprada, es donarà d\'alta a l\'inventari.',
	'Sin nº de serie, una fila con la misma descripción y el mismo tipo que un material que ya está en el inventario (o que otra fila del fichero) suma su cantidad a ese material en vez de crear otro. Las camisas del uniforme, solo si coinciden también el modelo y la talla.' => 'Sense núm. de sèrie, una fila amb la mateixa descripció i el mateix tipus que un material que ja és a l\'inventari (o que una altra fila del fitxer) suma la seva quantitat a aquest material en lloc de crear-ne un altre. Les camises de l\'uniforme, només si també coincideixen el model i la talla.',
	'Total estimado:' => 'Total estimat:',
	'Unidades a comprar, línea %d' => 'Unitats a comprar, línia %d',
	'Ya hay un material con esta descripción y este tipo, y sumándole esta cantidad pasaría de %d unidades.' => 'Ja hi ha un material amb aquesta descripció i aquest tipus, i sumant-li aquesta quantitat passaria de %d unitats.',
	'[%1$s] Tesorería ha rechazado tu lista de compra %2$s' => '[%1$s] Tresoreria ha rebutjat la teva llista de compra %2$s',
	'[%1$s] Tu lista de compra %2$s tiene el visto bueno de Tesorería' => '[%1$s] La teva llista de compra %2$s té el vistiplau de Tresoreria',
	'fila sumada a un material que ya estaba (misma descripción y tipo)' => 'fila sumada a un material que ja hi era (mateixa descripció i tipus)',
	'filas sumadas a un material que ya estaba (misma descripción y tipo)' => 'files sumades a un material que ja hi era (mateixa descripció i tipus)',
	'opcional' => 'opcional',
	'¿Marcar la lista %s como comprada? Las cantidades se sumarán al inventario y el material nuevo se dará de alta. No se puede deshacer.' => 'Vols marcar la llista %s com a comprada? Les quantitats se sumaran a l\'inventari i el material nou es donarà d\'alta. No es pot desfer.',
	'¿Ya se ha comprado?' => 'Ja s\'ha comprat?',
	'No has marcado ningún material del inventario. ¿Preparar una lista solo con material nuevo?' => 'No has marcat cap material de l\'inventari. Vols preparar una llista només amb material nou?',
	'Ya hay %s unidades de «%s» en el inventario. ¿Seguro que hace falta comprar más?' => 'A l\'inventari ja hi ha %s unitats de «%s». Segur que cal comprar-ne més?',
	'Ya hay 1 unidad de «%s» en el inventario. ¿Seguro que hace falta comprar más?' => 'A l\'inventari ja hi ha 1 unitat de «%s». Segur que cal comprar-ne més?',
	'Lista de compra revisada' => 'Llista de compra revisada',

	// v0.31: cambio de sección y cuota
	'Desde %1$s solo se puede pasar a %2$s, la siguiente por edad (solo los scouters cambian a cualquier sección).' => 'Des de %1$s només es pot passar a %2$s, la següent per edat (només els scouters canvien a qualsevol secció).',
	'Un educando pasa a la siguiente sección por edad.' => 'Un educand passa a la secció següent per edat.',
	'%d hijo/a' => '%d fill/a',
	'%d hijos/as' => '%d fills/es',
	'ajuste %s' => 'ajust %s',

	// v0.32: lista de espera
	'El enlace para apuntarse a la lista de espera, la lista para el equipo y el paso al CRM.' => 'L\'enllaç per apuntar-se a la llista d\'espera, la llista per a l\'equip i el pas al CRM.',
	'Si el botón no funciona, copia esta dirección en el navegador:' => 'Si el botó no funciona, copia aquesta adreça al navegador:',
	'¿Dudas? Escríbenos a %s.' => 'Dubtes? Escriu-nos a %s.',
	'Quién quiere entrar en el grupo, la sección que le toca por edad y su paso al CRM.' => 'Qui vol entrar al grup, la secció que li toca per edat i el seu pas al CRM.',
	'persona en la lista de espera sin contactar' => 'persona a la llista d\'espera sense contactar',
	'personas en la lista de espera sin contactar' => 'persones a la llista d\'espera sense contactar',
	'Contactada' => 'Contactada',
	'Descartada' => 'Descartada',
	'En espera' => 'En espera',
	'Plaza ofrecida' => 'Plaça oferta',
	'Sin confirmar el email' => 'Sense confirmar l\'email',
	'Lista de espera' => 'Llista d\'espera',
	'%1$s ya está en la lista de espera del %2$s. Te hemos enviado un email con el enlace para ver tus datos.' => '%1$s ja està a la llista d\'espera del %2$s. T\'hem enviat un email amb l\'enllaç per veure les teves dades.',
	'%d inscripciones' => '%d inscripcions',
	'%d inscripción' => '%d inscripció',
	'Abre el «Alta de socio/a» con sus datos. Primero se comprueba su documento en el CRM (si ya tiene ficha en el grupo, el alta se para). Al terminar el alta, esta inscripción se borra de la lista.' => 'Obre l\'«Alta de soci/sòcia» amb les seves dades. Primer es comprova el seu document al CRM (si ja té fitxa al grup, l\'alta s\'atura). En acabar l\'alta, aquesta inscripció s\'esborra de la llista.',
	'Acepto que el %1$s guarde estos datos, cifrados, para gestionar la lista de espera durante %2$d meses (o hasta que me dé de alta o los borre). Solo los ve el equipo del grupo.' => 'Accepto que el %1$s desi aquestes dades, xifrades, per gestionar la llista d\'espera durant %2$d mesos (o fins que em doni d\'alta o les esborri). Només les veu l\'equip del grup.',
	'Apellidos de la persona de contacto' => 'Cognoms de la persona de contacte',
	'Apuntada más de una vez con distinto email' => 'Apuntada més d\'una vegada amb un email diferent',
	'Apuntar a otra persona' => 'Apunta una altra persona',
	'Apuntar el contacto' => 'Apunta el contacte',
	'Apuntar un contacto hecho por otra vía' => 'Apunta un contacte fet per una altra via',
	'Apuntarme a la lista de espera' => 'Apunta\'m a la llista d\'espera',
	'Apúntate a la lista de espera del %s. Te avisaremos cuando haya plaza.' => 'Apunta\'t a la llista d\'espera del %s. T\'avisarem quan hi hagi plaça.',
	'Asignar' => 'Assigna',
	'Aún sin edad' => 'Encara sense edat',
	'Borrar de la lista' => 'Esborra de la llista',
	'Borrar mis datos' => 'Esborra les meves dades',
	'Cambiar el estado' => 'Canvia l\'estat',
	'Confirma la inscripción de <strong>%1$s</strong> en la lista de espera del <strong>%2$s</strong>.' => 'Confirma la inscripció de <strong>%1$s</strong> a la llista d\'espera del <strong>%2$s</strong>.',
	'Confirmar la inscripción' => 'Confirma la inscripció',
	'Contactar' => 'Contacta',
	'Contacto por email' => 'Contacte per email',
	'Contacto por teléfono' => 'Contacte per telèfon',
	'Cómo' => 'Com',
	'DNI o NIE' => 'DNI o NIE',
	'El email con el que te apuntaste' => 'L\'email amb el qual et vas apuntar',
	'El enlace vale %d días. Si no has sido tú, ignora este correo: la inscripción se borrará sola.' => 'L\'enllaç val %d dies. Si no has estat tu, ignora aquest correu: la inscripció s\'esborrarà sola.',
	'Email enviado: «%s»' => 'Email enviat: «%s»',
	'En la lista' => 'A la llista',
	'En la lista desde' => 'A la llista des de',
	'Enviar email' => 'Envia email',
	'Enviarme mis enlaces' => 'Envia\'m els meus enllaços',
	'Escribe un teléfono válido (al menos 9 cifras).' => 'Escriu un telèfon vàlid (almenys 9 xifres).',
	'Estado: %s' => 'Estat: %s',
	'Estas son las inscripciones con este email en la lista de espera del <strong>%s</strong>:' => 'Aquestes són les inscripcions amb aquest email a la llista d\'espera del <strong>%s</strong>:',
	'Este enlace no es válido o la inscripción ya no está en la lista (se borra al darse de alta en el grupo, al pedirlo o a los %d meses).' => 'Aquest enllaç no és vàlid o la inscripció ja no és a la llista (s\'esborra en donar-se d\'alta al grup, en demanar-ho o als %d mesos).',
	'Este enlace no es válido o ya no está en uso. Pide el enlace actual a tu grupo scout.' => 'Aquest enllaç no és vàlid o ja no s\'utilitza. Demana l\'enllaç actual al teu grup scout.',
	'Guarda este correo. Para ver tus datos te pediremos este email; desde ahí puedes mantenerlos o borrarlos cuando quieras.' => 'Guarda aquest correu. Per veure les teves dades et demanarem aquest email; des d\'allà pots mantenir-les o esborrar-les quan vulguis.',
	'Guardamos tus datos hasta' => 'Desem les teves dades fins al',
	'Guardamos tus datos, cifrados, hasta el %s. Antes te avisaremos para que puedas mantenerlos.' => 'Desem les teves dades, xifrades, fins al %s. Abans t\'avisarem perquè les puguis mantenir.',
	'Hecho: guardamos tus datos hasta el %s.' => 'Fet: desem les teves dades fins al %s.',
	'Hemos recibido la inscripción de <strong>%1$s</strong> en la lista de espera del <strong>%2$s</strong>.' => 'Hem rebut la inscripció de <strong>%1$s</strong> a la llista d\'espera del <strong>%2$s</strong>.',
	'Historial' => 'Historial',
	'Inscripción confirmada.' => 'Inscripció confirmada.',
	'Inscripción en la lista de espera del <strong>%s</strong>.' => 'Inscripció a la llista d\'espera del <strong>%s</strong>.',
	'La de su edad' => 'La de la seva edat',
	'La de su edad (%s)' => 'La de la seva edat (%s)',
	'La inscripción de <strong>%1$s</strong> en la lista de espera del <strong>%2$s</strong> está confirmada. Nos pondremos en contacto contigo cuando haya plaza.' => 'La inscripció de <strong>%1$s</strong> a la llista d\'espera del <strong>%2$s</strong> està confirmada. Ens posarem en contacte amb tu quan hi hagi plaça.',
	'La inscripción no tiene un email válido.' => 'La inscripció no té un email vàlid.',
	'Los datos de <strong>%1$s</strong> en la lista de espera del <strong>%2$s</strong> se borrarán el <strong>%3$s</strong>.' => 'Les dades de <strong>%1$s</strong> a la llista d\'espera del <strong>%2$s</strong> s\'esborraran el <strong>%3$s</strong>.',
	'Mantener mis datos' => 'Mantén les meves dades',
	'Mantener mis datos %d meses más' => 'Mantén les meves dades %d mesos més',
	'Mensaje' => 'Missatge',
	'No hay nadie en la lista de espera con este filtro.' => 'No hi ha ningú a la llista d\'espera amb aquest filtre.',
	'Nombre de la persona de contacto' => 'Nom de la persona de contacte',
	'Observaciones' => 'Observacions',
	'Para apuntarte tienes que aceptar el tratamiento de los datos.' => 'Per apuntar-te has d\'acceptar el tractament de les dades.',
	'Para corregir algún dato, escribe a tu grupo o borra la inscripción y vuelve a apuntarte con el enlace del grupo.' => 'Per corregir alguna dada, escriu al teu grup o esborra la inscripció i torna a apuntar-te amb l\'enllaç del grup.',
	'Para que entre en la lista, confirma que este email es tuyo:' => 'Perquè entri a la llista, confirma que aquest email és teu:',
	'Para ver tus datos de la lista de espera, escribe el email con el que te apuntaste.' => 'Per veure les teves dades de la llista d\'espera, escriu l\'email amb el qual et vas apuntar.',
	'Pasa este enlace a quien quiera entrar en el grupo. Deja sus datos, confirma su email y aparece aquí. Sus datos se guardan cifrados y se borran al darle de alta, si lo pide o a los 12 meses (salvo que diga que los mantiene).' => 'Passa aquest enllaç a qui vulgui entrar al grup. Deixa les seves dades, confirma el seu email i apareix aquí. Les seves dades es desen xifrades i s\'esborren en donar-lo d\'alta, si ho demana o als 12 mesos (tret que digui que les manté).',
	'Persona de contacto' => 'Persona de contacte',
	'Por debajo de %d años, escribe el nombre y los apellidos de la madre, el padre o el tutor/a.' => 'Per sota dels %d anys, escriu el nom i els cognoms de la mare, el pare o el tutor/a.',
	'Puedes responder a este correo. Estás en la lista de espera del %1$s: <a href="%2$s">ver mis datos</a>.' => 'Pots respondre a aquest correu. Ets a la llista d\'espera del %1$s: <a href="%2$s">veure les meves dades</a>.',
	'Quiero borrar mis datos y salir de la lista de espera. No se puede deshacer.' => 'Vull esborrar les meves dades i sortir de la llista d\'espera. No es pot desfer.',
	'Quién quiere entrar en el grupo' => 'Qui vol entrar al grup',
	'Repetida' => 'Repetida',
	'Se apuntó' => 'Es va apuntar',
	'Se envía desde la web con el email de contacto del grupo para las respuestas, queda en el historial y la inscripción pasa a «Contactada».' => 'S\'envia des del web amb l\'email de contacte del grup per a les respostes, queda a l\'historial i la inscripció passa a «Contactada».',
	'Sección asignada' => 'Secció assignada',
	'Sección asignada: %s' => 'Secció assignada: %s',
	'Sección por edad' => 'Secció per edat',
	'Sección y alta' => 'Secció i alta',
	'Sección: la de su edad' => 'Secció: la de la seva edat',
	'Si %s está en alguna lista de espera, te hemos enviado un email con tus enlaces.' => 'Si %s és a alguna llista d\'espera, t\'hem enviat un email amb els teus enllaços.',
	'Si el enlace ha llegado a quien no debía. Los enlaces personales de cada inscripción siguen valiendo.' => 'Si l\'enllaç ha arribat a qui no devia. Els enllaços personals de cada inscripció continuen valent.',
	'Si es menor de %d años, los datos de la madre, el padre o el tutor/a.' => 'Si és menor de %d anys, les dades de la mare, el pare o el tutor/a.',
	'Si no haces nada, se borrarán ese día y saldrás de la lista.' => 'Si no fas res, s\'esborraran aquell dia i sortiràs de la llista.',
	'Si no has pedido tú estos enlaces, puedes ignorar este correo.' => 'Si no has demanat tu aquests enllaços, pots ignorar aquest correu.',
	'Si no te llega, mira en el correo no deseado. El enlace vale %d días.' => 'Si no t\'arriba, mira al correu brossa. L\'enllaç val %d dies.',
	'Si quieres seguir en la lista, entra y pulsa «Mantener mis datos»: los guardaremos %d meses más.' => 'Si vols continuar a la llista, entra i prem «Mantén les meves dades»: les desarem %d mesos més.',
	'Sus datos se borran el' => 'Les seves dades s\'esborren el',
	'Sí (lo ven Secretaría y Coordinación)' => 'Sí (ho veuen Secretaria i Coordinació)',
	'Te enviaremos un email para confirmarlo. Es también tu clave para ver tus datos más adelante.' => 'T\'enviarem un email per confirmar-ho. És també la teva clau per veure les teves dades més endavant.',
	'Te hemos enviado un email a %s para confirmar la inscripción. Hasta que no pulses su enlace, no entra en la lista.' => 'T\'hem enviat un email a %s per confirmar la inscripció. Fins que no premis el seu enllaç, no entra a la llista.',
	'Te hemos enviado un email para confirmar la inscripción. Hasta que no pulses su enlace, no entra en la lista.' => 'T\'hem enviat un email per confirmar la inscripció. Fins que no premis el seu enllaç, no entra a la llista.',
	'Teléfono' => 'Telèfon',
	'Todavía no ha confirmado su email: no entra en la lista hasta que lo haga. Si no lo confirma en %d días, se borra sola.' => 'Encara no ha confirmat el seu email: no entra a la llista fins que ho faci. Si no el confirma en %d dies, s\'esborra sola.',
	'Tus datos se han borrado y ya no estás en la lista de espera.' => 'Les teves dades s\'han esborrat i ja no ets a la llista d\'espera.',
	'Ver mis datos' => 'Veure les meves dades',
	'[%s] Confirma la inscripción en la lista de espera' => '[%s] Confirma la inscripció a la llista d\'espera',
	'[%s] Inscripción confirmada en la lista de espera' => '[%s] Inscripció confirmada a la llista d\'espera',
	'[%s] Tus datos de la lista de espera caducan pronto' => '[%s] Les teves dades de la llista d\'espera caduquen aviat',
	'[%s] Tus enlaces de la lista de espera' => '[%s] Els teus enllaços de la llista d\'espera',
	'asignada' => 'assignada',
	'confirmó el %s' => 'va confirmar el %s',
	'sin confirmar: el enlace la confirma' => 'sense confirmar: l\'enllaç la confirma',
	'¿Borrar a %s de la lista de espera? Sus datos se borran y no se puede deshacer.' => 'Vols esborrar %s de la llista d\'espera? Les seves dades s\'esborren i no es pot desfer.',
	'¿Ya estás en la lista? Recibe tus enlaces' => 'Ja ets a la llista? Rep els teus enllaços',
	'Último contacto: %1$s, %2$s' => 'Últim contacte: %1$s, %2$s',
	'← Lista de espera' => '← Llista d\'espera',
