	'Las altas en el CRM no están activadas para tu grupo (wp-admin → Grupos Scouts → Módulos).' => 'Les altes al CRM no estan activades per al teu grup (wp-admin → Grupos Scouts → Módulos).',
	'Lista de espera del %s' => 'Llista d\'espera del %s',
	'Marca la casilla para confirmar que quieres borrar tus datos.' => 'Marca la casella per confirmar que vols esborrar les teves dades.',
	'No se ha podido apuntar el contacto.' => 'No s\'ha pogut apuntar el contacte.',
	'No se ha podido asignar la sección.' => 'No s\'ha pogut assignar la secció.',
	'No se ha podido cambiar el estado.' => 'No s\'ha pogut canviar l\'estat.',
	'Sección asignada: %s.' => 'Secció assignada: %s.',
	'Sección: la de su edad.' => 'Secció: la de la seva edat.',
