	'Ver la inscripción' => 'Veure la inscripció',
	'Viene de la lista de espera: los datos son los que escribió la familia. Revísalos y completa lo que falta (el género). Al terminar, la inscripción se borra de la lista.' => 'Ve de la llista d\'espera: les dades són les que ha escrit la família. Revisa-les i completa el que falta (el gènere). En acabar, la inscripció s\'esborra de la llista.',

	// v0.32: lista de espera (orden)
	'Orden' => 'Ordre',
	'Orden de llegada en su sección' => 'Ordre d\'arribada a la seva secció',

	// v0.33: la cuenta en la ficha del CRM
	'%1$s: %2$s' => '%1$s: %2$s',
	'El CRM no ha guardado la cuenta en la ficha. Inténtalo más tarde o avisa a la Tesorería del grupo.' => 'El CRM no ha desat el compte a la fitxa. Torna-ho a provar més tard o avisa la Tresoreria del grup.',
	'El CRM no responde: inténtalo más tarde.' => 'El CRM no respon: torna-ho a provar més tard.',
	'Familia %s: la cuenta de su ficha del CRM ya no es la autorizada.' => 'Família %s: el compte de la seva fitxa del CRM ja no és l\'autoritzat.',
	'La cuenta de su ficha del CRM no es la autorizada (o no está): tiene que firmar la autorización de nuevo' => 'El compte de la seva fitxa del CRM no és l\'autoritzat (o no hi és): ha de signar l\'autorització de nou',
	'La cuenta se guarda en la ficha del CRM y el usuario del CRM de tu grupo no tiene permiso para editar fichas. Avisa a la Tesorería del grupo.' => 'El compte es desa a la fitxa del CRM i l\'usuari del CRM del teu grup no té permís per editar fitxes. Avisa la Tresoreria del grup.',
	'La ficha del CRM solo admite cuentas de hasta %d caracteres (las españolas tienen 24): usa una cuenta española.' => 'La fitxa del CRM només admet comptes de fins a %d caràcters (les espanyoles en tenen 24): fes servir un compte espanyol.',
	'No se encuentran en el CRM las fichas de la familia.' => 'No es troben al CRM les fitxes de la família.',
	'No se ha podido leer la cuenta de las familias en el CRM: inténtalo más tarde.' => 'No s\'ha pogut llegir el compte de les famílies al CRM: torna-ho a provar més tard.',
	'Autorización de cobro (SEPA)' => 'Autorització de cobrament (SEPA)',
	'Cuenta (IBAN)' => 'Compte (IBAN)',
	'Datos bancarios y domiciliación SEPA' => 'Dades bancàries i domiciliació SEPA',
	'Entidad' => 'Entitat',
	'Los datos bancarios se guardan en la ficha del CRM de Scouts de España (en la de cada miembro de la familia). Para ponerlos o cambiarlos, la madre, el padre, el tutor/a o el propio asociado mayor de edad firma una autorización en «Mis pagos».' => 'Les dades bancàries es desen a la fitxa del CRM de Scouts de España (a la de cada membre de la família). Per posar-les o canviar-les, la mare, el pare, el tutor/a o el mateix soci/sòcia major d\'edat signa una autorització a «Els meus pagaments».',
	'Sin autorización: la familia paga por transferencia.' => 'Sense autorització: la família paga per transferència.',
	'Sin datos bancarios en la ficha' => 'Sense dades bancàries a la fitxa',
	'Vigente · %1$s · firmada el %2$s' => 'Vigent · %1$s · signada el %2$s',
	'⚠️ La cuenta de esta ficha no es la autorizada: no se cobrará hasta que se firme una autorización nueva.' => '⚠️ El compte d\'aquesta fitxa no és l\'autoritzat: no es cobrarà fins que se signi una autorització nova.',
	'Cuenta española (24 caracteres). Se guarda, con el titular y la entidad, en la ficha de cada miembro de la familia en el CRM de Scouts de España; la web solo guarda tu autorización.' => 'Compte espanyol (24 caràcters). Es desa, amb el titular i l\'entitat, a la fitxa de cada membre de la família al CRM de Scouts de España; el web només desa la teva autorització.',
	'Entidad (banco, opcional)' => 'Entitat (banc, opcional)',
	'Los datos de la cuenta se guardan en la ficha de cada miembro de la familia en el CRM de Scouts de España; aquí solo se enseña enmascarada.' => 'Les dades del compte es desen a la fitxa de cada membre de la família al CRM de Scouts de España; aquí el compte només es mostra emmascarat.',
	'⚠️ La cuenta que figura en la ficha del CRM ya no es la que autorizaste: hasta que firmes una autorización nueva no se cobrará nada por domiciliación.' => '⚠️ El compte que figura a la fitxa del CRM ja no és el que vas autoritzar: fins que no signis una autorització nova no es cobrarà res per domiciliació.',
	'Autorizar el cobro o cambiar la cuenta en «Mis pagos»' => 'Autoritzar el cobrament o canviar el compte a «Els meus pagaments»',
	'Cuentas pasadas a las fichas del CRM: %1$d. Autorizaciones anuladas de las que se ha borrado la cuenta: %2$d.' => 'Comptes passats a les fitxes del CRM: %1$d. Autoritzacions anul·lades de les quals s\'ha esborrat el compte: %2$d.',
	'Ver las domiciliaciones (Tesorería)' => 'Veure les domiciliacions (Tresoreria)',
	'Hay autorizaciones firmadas antes de la versión 0.33 que guardan la cuenta en la web. Pásalas a las fichas del CRM: desde entonces la web ya no guarda ninguna cuenta.' => 'Hi ha autoritzacions signades abans de la versió 0.33 que desen el compte al web. Passa-les a les fitxes del CRM: des d\'aleshores el web ja no desa cap compte.',
	'La cuenta (IBAN, titular y entidad) se guarda en la ficha del CRM de Scouts de España de cada miembro de la familia; la web guarda la autorización (quién la firmó y cuándo, y la dirección), el IBAN enmascarado y una huella para comprobar, antes de cobrar, que la cuenta del CRM sigue siendo la autorizada. La autorización se conserva mientras esté vigente y 14 meses después de anularla, como pide la norma SEPA.' => 'El compte (IBAN, titular i entitat) es desa a la fitxa del CRM de Scouts de España de cada membre de la família; el web desa l\'autorització (qui la va signar i quan, i l\'adreça), l\'IBAN emmascarat i una empremta per comprovar, abans de cobrar, que el compte del CRM continua sent l\'autoritzat. L\'autorització es conserva mentre sigui vigent i 14 mesos després d\'anul·lar-la, com demana la norma SEPA.',
	'Pasar las cuentas al CRM' => 'Passar els comptes al CRM',
	'Titular: %s' => 'Titular: %s',
	'¿Pasar las cuentas de las autorizaciones a las fichas del CRM? Se escriben en la ficha de cada miembro de la familia y se borran de la web.' => 'Vols passar els comptes de les autoritzacions a les fitxes del CRM? S\'escriuen a la fitxa de cada membre de la família i s\'esborren del web.',
	'⚠️ La cuenta de su ficha del CRM no es la autorizada (o no está): no se le cobrará hasta que firme de nuevo.' => '⚠️ El compte de la seva fitxa del CRM no és l\'autoritzat (o no hi és): no se li cobrarà fins que signi de nou.',

