	'Actividad internacional: hace falta un seguro aparte (compañía y nº de póliza).' => 'Activitat internacional: cal una assegurança a part (companyia i núm. de pòlissa).',
	'Agenda' => 'Agenda',
	'Ahora mismo no hay ningún evento abierto para ti ni para tu familia. Cuando el grupo publique uno, te llegará un email.' => 'Ara mateix no hi ha cap esdeveniment obert per a tu ni per a la teva família. Quan el grup en publiqui un, t\'arribarà un correu.',
	'Ahora no se puede responder a esta convocatoria.' => 'Ara no es pot respondre a aquesta convocatòria.',
	'Ajuste guardado: el importe de la inscripción ha cambiado.' => 'Ajust desat: l\'import de la inscripció ha canviat.',
	'Al coste de cada participante se le suma este margen: es el fondo de emergencia de la actividad. Es el valor con el que nace cada evento nuevo; en cada uno se puede cambiar hasta que Tesorería valida su presupuesto.' => 'Al cost de cada participant s\'hi suma aquest marge: és el fons d\'emergència de l\'activitat. És el valor amb què neix cada esdeveniment nou; en cadascun es pot canviar fins que Tresoreria en valida el pressupost.',
	'Al día' => 'Al dia',
	'Al inscribir firmas la autorización: queda registrado quién la firma, cuándo y qué versión del texto.' => 'En inscriure signes l\'autorització: queda registrat qui la signa, quan i quina versió del text.',
	'Al menos la mitad de los monitores tiene que tener la titulación de tiempo libre: hay %1$d titulados de %2$d.' => 'Almenys la meitat dels monitors ha de tenir la titulació de lleure: hi ha %1$d titulats de %2$d.',
