	'Cada tipo da los valores con los que nace un evento: si tiene coste y si se comunica a ASDE Baleares (las actividades de 2 o más noches con 10 o más menores).' => 'Cada tipus dona els valors amb què neix un esdeveniment: si té cost i si es comunica a ASDE Balears (les activitats de 2 o més nits amb 10 o més menors).',
	'Caducado al acabar' => 'Caducat en acabar',
