	'Cerrado: solo inscribe el equipo del evento' => 'Tancat: només inscriu l\'equip de l\'esdeveniment',
	'Certificado' => 'Certificat',
	'Como madre, padre o tutor/a legal, autorizo su participación en esta actividad del grupo scout, organizada bajo la responsabilidad de su equipo de scouters, y declaro que he leído la información de la actividad. Autorizo también que, en caso de urgencia y si no se me puede localizar, el equipo tome las decisiones médicas, quirúrgicas o de traslado que indique el personal sanitario.' => 'Com a mare, pare o tutor/a legal, autoritzo la seva participació en aquesta activitat del grup escolta, organitzada sota la responsabilitat del seu equip de scouters, i declaro que he llegit la informació de l\'activitat. Autoritzo també que, en cas d\'urgència i si no se\'m pot localitzar, l\'equip prengui les decisions mèdiques, quirúrgiques o de trasllat que indiqui el personal sanitari.',
	'Como mucho %d tipos de actividad.' => 'Com a màxim %d tipus d\'activitat.',
