	'El certificado de delitos sexuales de %s tendrá más de 12 meses cuando acabe el evento: hay que renovarlo.' => 'El certificat de delictes sexuals de %s tindrà més de 12 mesos quan acabi l\'esdeveniment: cal renovar-lo.',
