	'El precio se calcula con los participantes previstos y, una vez validado, ya no cambia: lo que sobre o falte lo asume el grupo.' => 'El preu es calcula amb els participants previstos i, un cop validat, ja no canvia: el que sobri o falti ho assumeix el grup.',
