	'El presupuesto ya está validado y el precio es fijo: para cambiar las secciones, los participantes previstos o si tiene coste, pide a Tesorería que reabra el presupuesto.' => 'El pressupost ja està validat i el preu és fix: per canviar les seccions, els participants previstos o si té cost, demana a Tresoreria que reobri el pressupost.',
