	'Sin fecha' => 'Sense data',
	'Sin fechas, la inscripción se abre al publicar y se cierra cuando empieza el evento. Pasado el plazo, solo inscribe el equipo. Si no quedan plazas, las nuevas inscripciones entran en la lista de espera.' => 'Sense dates, la inscripció s\'obre en publicar i es tanca quan comença l\'esdeveniment. Passat el termini, només inscriu l\'equip. Si no queden places, les inscripcions noves entren a la llista d\'espera.',
