	'Un evento nace como borrador; si tiene coste, Tesorería valida su presupuesto (y con él, el precio) antes de publicarlo.' => 'Un esdeveniment neix com a esborrany; si té cost, Tresoreria en valida el pressupost (i amb ell, el preu) abans de publicar-lo.',
