	'por persona' => 'per persona',
	'que tu familia firme la autorización de participación desde su cuenta (o la entregue en papel al equipo).' => 'que la teva família signi l\'autorització de participació des del seu compte (o la lliuri en paper a l\'equip).',
	'«Por persona: participantes y equipo» es lo que cuesta cada persona (albergue, comida): lo del equipo se reparte entre los participantes. «Solo el equipo» es lo que cuesta un scouter (p. ej. su plaza en un evento externo).' => '«Per persona: participants i equip» és el que costa cada persona (alberg, menjar): el de l\'equip es reparteix entre els participants. «Només l\'equip» és el que costa un scouter (p. ex. la seva plaça en un esdeveniment extern).',
	'¿Anular este movimiento? Si es un pago de la familia, se anula entero.' => 'Vols anul·lar aquest moviment? Si és un pagament de la família, s\'anul·la sencer.',
	'¿Borrar este borrador con su equipo y su presupuesto? No se puede deshacer.' => 'Vols esborrar aquest esborrany amb el seu equip i el seu pressupost? No es pot desfer.',
