	// v0.35.1: familias, eliminar de la web
	'Eliminar de la web' => 'Elimina del web',
	'No tiene membresía activa: deja de salir en Personas, sale de su familia y sus cuentas de acceso se desactivan. En el CRM no cambia nada; si vuelve a tener una membresía activa, vuelve a salir.' => 'No té membresia activa: deixa de sortir a Persones, surt de la seva família i els seus comptes d\'accés es desactiven. Al CRM no canvia res; si torna a tenir una membresia activa, torna a sortir.',
	'¿Eliminar a %s de la web? Deja de salir en Personas, sale de su familia y sus cuentas de acceso se desactivan. En el CRM no cambia nada.' => 'Vols eliminar %s del web? Deixa de sortir a Persones, surt de la seva família i els seus comptes d\'accés es desactiven. Al CRM no canvia res.',
	'No hay ningún grupo elegido.' => 'No hi ha cap grup triat.',
	'Solo se puede eliminar de la web a quien no tiene ninguna membresía activa. Antes, dale de baja.' => 'Només es pot eliminar del web qui no té cap membresia activa. Abans, dona-li de baixa.',
	'%s ya no sale en la web. En el CRM no ha cambiado nada.' => '%s ja no surt al web. Al CRM no ha canviat res.',
	'Familia eliminada.' => 'Família eliminada.',
	'Ha salido de la familia nº %s.' => 'Ha sortit de la família núm. %s.',
	'Su cuenta de acceso se ha desactivado.' => 'El seu compte d\'accés s\'ha desactivat.',
	'Ya no está en %1$d cuenta(s) familiar(es); %2$d se han desactivado porque no representan a nadie más.' => 'Ja no és a %1$d compte(s) familiar(s); %2$d s\'han desactivat perquè no representen ningú més.',
	'Eliminar' => 'Elimina',
	'Eliminar esta familia' => 'Elimina aquesta família',
	'Solo se puede eliminar una familia sin socios.' => 'Només es pot eliminar una família sense socis.',
	'Tiene autorizaciones de domiciliación: no se puede eliminar.' => 'Té autoritzacions de domiciliació: no es pot eliminar.',
	'Tiene movimientos del banco asignados: no se puede eliminar.' => 'Té moviments del banc assignats: no es pot eliminar.',
