	'Por defecto, el número y el nombre del evento' => 'Per defecte, el número i el nom de l\'esdeveniment',
	'Un adeudo por familia con autorización, con todo lo pendiente de sus inscripciones activas en el evento (los hermanos, juntos). Al registrar los cobros, el importe se reparte entre sus inscripciones.' => 'Un càrrec per família amb autorització, amb tot el que tenen pendent les seves inscripcions actives a l\'esdeveniment (els germans, junts). En registrar els cobraments, l\'import es reparteix entre les seves inscripcions.',

	// v0.36.1: reabrir las cuentas
	'Al cerrar, el balance de hoy queda como informe final, se borran los datos de recogida y las observaciones de las inscripciones y el evento queda en solo lectura. Si después hace falta cambiar algo, Tesorería puede reabrirlas (lo borrado no vuelve).' => 'En tancar, el balanç d\'avui queda com a informe final, s\'esborren les dades de recollida i les observacions de les inscripcions i l\'esdeveniment queda en només lectura. Si després cal canviar alguna cosa, Tresoreria els pot reobrir (el que s\'ha esborrat no torna).',
	'Cuentas cerradas el %1$s por %2$s: este es el informe final. Para cambiar algo, Tesorería tiene que reabrirlas.' => 'Comptes tancats el %1$s per %2$s: aquest és l\'informe final. Per canviar alguna cosa, Tresoreria els ha de reobrir.',
	'Cuentas del evento %s reabiertas: ya se pueden cambiar. Cuando esté todo, ciérralas de nuevo.' => 'Comptes de l\'esdeveniment %s reoberts: ja es poden canviar. Quan estigui tot, torna\'ls a tancar.',
	'Escribe el motivo para reabrir las cuentas.' => 'Escriu el motiu per reobrir els comptes.',
	'Las cuentas de este evento no están cerradas.' => 'Els comptes d\'aquest esdeveniment no estan tancats.',
	'Las cuentas las reabre Tesorería.' => 'Els comptes els reobre Tresoreria.',
	'No se han podido reabrir las cuentas. Inténtalo de nuevo.' => 'No s\'han pogut reobrir els comptes. Torna-ho a provar.',
	'Reabrir las cuentas' => 'Reobre els comptes',
	'Se podrá volver a cambiar el evento y sus cuentas. Quién recoge y las observaciones, que se borraron al cerrar, no vuelven.' => 'Es podrà tornar a canviar l\'esdeveniment i els seus comptes. Qui recull i les observacions, que es van esborrar en tancar, no tornen.',
	'¿Cerrar las cuentas del evento? Quién recoge y las observaciones de las inscripciones se borran y no vuelven.' => 'Vols tancar els comptes de l\'esdeveniment? Qui recull i les observacions de les inscripcions s\'esborren i no tornen.',
	'¿Reabrir las cuentas del evento? Habrá que volver a cerrarlas.' => 'Vols reobrir els comptes de l\'esdeveniment? Caldrà tornar-los a tancar.',

