	'%d familia' => '%d família',
	'%d familias' => '%d famílies',
	'El ingreso del banco solo se asocia a la cuota de la ronda. Para un evento, quita el ingreso y escribe el pago.' => 'L\'ingrés del banc només s\'associa a la quota de la ronda. Per a un esdeveniment, treu l\'ingrés i escriu el pagament.',
	'Ese evento no está abierto a inscripciones o esta familia no tiene nada pendiente en él.' => 'Aquest esdeveniment no està obert a inscripcions o aquesta família no hi té res pendent.',
