	'Pago de %1$s · pedido de uniforme %2$s' => 'Pagament de %1$s · comanda d\'uniforme %2$s',
	'Solo salen los eventos con la inscripción abierta en los que esta familia tiene algo pendiente. Para un evento: efectivo, transferencia o Bizum, y sin ingreso del banco.' => 'Només surten els esdeveniments amb la inscripció oberta en què aquesta família té alguna cosa pendent. Per a un esdeveniment: efectiu, transferència o Bizum, i sense ingrés del banc.',
	'Todo lo que ha pagado esta familia: la cuota de la ronda, los eventos y los uniformes, con quién lo registró y cuándo. Lo eliminado no cuenta.' => 'Tot el que ha pagat aquesta família: la quota de la ronda, els esdeveniments i els uniformes, amb qui ho va registrar i quan. El que s\'ha eliminat no compta.',
