	'(opcional)' => '(opcional)',
	'Además de los datos que siempre se piden, tu grupo puede añadir preguntas al formulario de la lista de espera. Cada campo necesita su etiqueta (el texto que verá quien se apunta) y se elige su tipo y si es obligatorio. Las respuestas se guardan cifradas con la clave del email de quien se apunta y se borran con la inscripción. Quitar o cambiar un campo no altera lo que ya contestaron.' => 'A més de les dades que sempre es demanen, el vostre grup pot afegir preguntes al formulari de la llista d\'espera. Cada camp necessita la seva etiqueta (el text que veurà qui s\'apunta) i es tria el tipus i si és obligatori. Les respostes es guarden xifrades amb la clau de l\'email de qui s\'apunta i s\'esborren amb la inscripció. Treure o canviar un camp no altera el que ja han contestat.',
	'Cada campo necesita su etiqueta: es el texto que verá quien se apunta.' => 'Cada camp necessita la seva etiqueta: és el text que veurà qui s\'apunta.',
	'Campos propios del formulario' => 'Camps propis del formulari',
	'Como máximo, %d campos propios.' => 'Com a màxim, %d camps propis.',
	'Elige el tipo de cada campo.' => 'Tria el tipus de cada camp.',
