	'Falta rellenar «%s».' => 'Falta omplir «%s».',
	'Guardar los campos' => 'Desa els camps',
	'Las filas vacías se ignoran. Para añadir más campos, guarda y vuelve a abrir este cuadro. Máximo %d campos.' => 'Les files buides s\'ignoren. Per afegir més camps, desa i torna a obrir aquest quadre. Màxim %d camps.',
	'Más datos que pide el grupo' => 'Més dades que demana el grup',
	'Obligatorio' => 'Obligatori',
	'Opcional' => 'Opcional',
