	'Corrígelas y vuelve a cargar solo esas filas (las demás ya están en la tienda). Puedes descargarlas en un CSV con el motivo de cada una.' => 'Corregeix-les i torna a carregar només aquestes files (les altres ja són a la botiga). Les pots baixar en un CSV amb el motiu de cadascuna.',
	'El informe de esa carga ya no está disponible (se guarda una hora).' => 'L\'informe d\'aquesta càrrega ja no està disponible (es guarda una hora).',
	'En venta' => 'En venda',
	'Existencias' => 'Existències',
	'Filas que no se han cargado' => 'Files que no s\'han carregat',
	'Guardar y añadir otro' => 'Desar i afegir-ne un altre',
	'Lo que está aquí es lo que la tienda puede vender. Cada producto tiene una o varias variantes (tallas, colores…) con sus existencias. Los «solo socios» solo los ven quienes han iniciado sesión.' => 'El que hi ha aquí és el que la botiga pot vendre. Cada producte té una o diverses variants (talles, colors…) amb les seves existències. Els «només socis» només els veuen els qui han iniciat la sessió.',
	'Motivo del cambio de existencias (opcional)' => 'Motiu del canvi d\'existències (opcional)',
	'Máximo por persona (0 = sin límite)' => 'Màxim per persona (0 = sense límit)',
	'No hay productos con ese filtro. Empieza con «Añadir producto» o, si ya los tienes en una hoja de cálculo, con «Cargar desde CSV».' => 'No hi ha productes amb aquest filtre. Comença amb «Afegir producte» o, si ja els tens en un full de càlcul, amb «Carregar des d\'un CSV».',
	'Nombre o referencia' => 'Nom o referència',
	'Nuevo producto' => 'Producte nou',
	'Obligatoria: %s.' => 'Obligatòria: %s.',
	'Por confirmar' => 'Per confirmar',
	'Por ejemplo: llegada del pedido, recuento…' => 'Per exemple: arribada de la comanda, recompte…',
	'Precio de socio (€, opcional)' => 'Preu de soci (€, opcional)',
	'Precio propio' => 'Preu propi',
	'Precio propio (€)' => 'Preu propi (€)',
	'Prepara los productos en una hoja de cálculo, guárdala como CSV y súbela aquí. Cada fila es una variante (una talla, un color…); varias filas con el mismo producto son variantes del mismo producto. Primero se comprueba el fichero; después se cargan las filas correctas y verás las que no, con el motivo.' => 'Prepara els productes en un full de càlcul, desa\'l com a CSV i puja\'l aquí. Cada fila és una variant (una talla, un color…); diverses files amb el mateix producte són variants del mateix producte. Primer es comprova el fitxer; després es carreguen les files correctes i veuràs les que no, amb el motiu.',
	'Producto' => 'Producte',
	'Quién lo ve y lo puede comprar' => 'Qui el veu i el pot comprar',
	'Recuperar el producto' => 'Recuperar el producte',
	'Resultado de la carga' => 'Resultat de la càrrega',
	'Se encarga al proveedor (pasa por «incluido en el pedido del grupo» antes de entregarse)' => 'Es demana al proveïdor (passa per «inclòs a la comanda del grup» abans de lliurar-se)',
	'Si lo pones, los socios con sesión pagan este precio en vez del general.' => 'Si el poses, els socis amb la sessió iniciada paguen aquest preu en lloc del general.',
	'Sin límite' => 'Sense límit',
	'Solo socios' => 'Només socis',
	'Sumar las existencias a las que ya hay (si no, las existencias del fichero sustituyen a las actuales)' => 'Sumar les existències a les que ja hi ha (si no, les existències del fitxer substitueixen les actuals)',
	'Todas las filas se han cargado.' => 'Totes les files s\'han carregat.',
	'Un producto que ya existe (mismo nombre) se actualiza solo con las celdas rellenas: una celda vacía no borra nada. Una variante que ya existe cambia sus existencias.' => 'Un producte que ja existeix (mateix nom) s\'actualitza només amb les cel·les omplertes: una cel·la buida no esborra res. Una variant que ja existeix canvia les seves existències.',
	'Un producto «solo socios» no sale a quien no ha iniciado sesión, ni en la lista ni con su dirección.' => 'Un producte «només socis» no surt a qui no ha iniciat la sessió, ni a la llista ni amb la seva adreça.',
	'Vacío = «precio por confirmar»: se puede pedir y Tesorería cobra el importe real.' => 'Buit = «preu per confirmar»: es pot demanar i Tresoreria cobra l\'import real.',
