	'Ver también los archivados' => 'Veure també els arxivats',
	'Visibilidad: «todos» o «socios». El precio, con coma o punto para los decimales (12,50); vacío = precio por confirmar. Existencias: un número entero o «ilimitado».' => 'Visibilitat: «tots» o «socis». El preu, amb coma o punt per als decimals (12,50); buit = preu per confirmar. Existències: un nombre enter o «ilimitado».',
