	// v0.39 fase 4: tienda pública
	'%s (sin sesión)' => '%s (sense sessió)',
	'Compra sin sesión' => 'Compra sense sessió',
	'Escribe tu nombre y un email válido: ahí te mandamos el pedido.' => 'Escriu el teu nom i un email vàlid: allà t\'enviem la comanda.',
	'Ver mi pedido' => 'Veure la meva comanda',
	'Enlace nuevo creado. El anterior ya no vale.' => 'Enllaç nou creat. L\'anterior ja no val.',
	'Ese pedido ya no se puede cancelar desde aquí. Escribe al grupo.' => 'Aquesta comanda ja no es pot cancel·lar des d\'aquí. Escriu al grup.',
	'No se ha podido enviar el pedido. Vuelve a intentarlo.' => 'No s\'ha pogut enviar la comanda. Torna-ho a provar.',
	'Abrir la tienda pública (compra sin sesión)' => 'Obrir la botiga pública (compra sense sessió)',
	'Cancelado el %s.' => 'Cancel·lada el %s.',
	'Con la tienda pública, cualquiera con el enlace puede comprar sin iniciar sesión lo que el grupo tenga a la venta «para todos» (nunca lo «solo socios»), pagando por transferencia o Bizum. Sus datos se guardan cifrados y se borran a los 90 días de entregar o cancelar el pedido.' => 'Amb la botiga pública, qualsevol persona amb l\'enllaç pot comprar sense iniciar sessió el que el grup tingui a la venda «per a tothom» (mai el «només socis»), pagant per transferència o Bizum. Les seves dades es guarden xifrades i s\'esborren als 90 dies de lliurar o cancel·lar la comanda.',
	'Crear un enlace nuevo' => 'Crea un enllaç nou',
	'Días para pagar una compra sin sesión antes de cancelarla (0 = nunca)' => 'Dies per pagar una compra sense sessió abans de cancel·lar-la (0 = mai)',
	'Elige lo que quieres, deja tus datos y te mandamos por email el pedido y cómo pagarlo.' => 'Tria el que vols, deixa les teves dades i t\'enviem per email la comanda i com pagar-la.',
	'Enlace de la tienda' => 'Enllaç de la botiga',
	'Enlace de la tienda (compártelo donde quieras):' => 'Enllaç de la botiga (comparteix-lo on vulguis):',
	'Esta dirección no es válida o la tienda no está abierta ahora mismo. Pide el enlace al grupo.' => 'Aquesta adreça no és vàlida o la botiga no és oberta ara mateix. Demana l\'enllaç al grup.',
	'Este enlace no es válido o ya ha caducado.' => 'Aquest enllaç no és vàlid o ja ha caducat.',
	'Guardamos tu nombre, email y teléfono cifrados solo para gestionar este pedido, y los borramos a los 90 días de entregarlo o cancelarlo.' => 'Guardem el teu nom, email i telèfon xifrats només per gestionar aquesta comanda, i els esborrem als 90 dies de lliurar-la o cancel·lar-la.',
	'Nombre y apellidos' => 'Nom i cognoms',
	'Si el enlace se ha compartido donde no debía, crea uno nuevo: el anterior deja de valer (guarda antes los cambios de esta pantalla).' => 'Si l\'enllaç s\'ha compartit on no tocava, crea\'n un de nou: l\'anterior deixa de valer (desa abans els canvis d\'aquesta pantalla).',
	'Si no se paga en %d días, el pedido se cancela y los artículos vuelven a la tienda.' => 'Si no es paga en %d dies, la comanda es cancel·la i els articles tornen a la botiga.',
	'Teléfono (opcional)' => 'Telèfon (opcional)',
	'Tienda de %s' => 'Botiga de %s',
	'Tienda pública' => 'Botiga pública',
	'Todavía no hay nada a la venta.' => 'Encara no hi ha res a la venda.',
	'¡Pedido recibido! Te hemos mandado un email con este enlace: guárdalo para seguir tu pedido.' => 'Comanda rebuda! T\'hem enviat un email amb aquest enllaç: desa\'l per seguir la teva comanda.',

	// v0.39: texto de pago del uniforme

	// v0.40 fase 5: recordatorio, banco e informes de la tienda
	'El pedido %s se ha cancelado porque no se pagó a tiempo, y lo que pediste ha vuelto a la tienda. Si todavía lo quieres, puedes hacer un pedido nuevo.' => 'La comanda %s s\'ha cancel·lat perquè no es va pagar a temps, i el que vas demanar ha tornat a la botiga. Si encara ho vols, pots fer una comanda nova.',
	'Si no se paga antes del %s, se cancelará y lo que pediste volverá a la tienda.' => 'Si no es paga abans del %s, es cancel·larà i el que vas demanar tornarà a la botiga.',
	'Te recordamos que el pedido %s sigue sin pagar.' => 'Et recordem que la comanda %s continua sense pagar.',
	'El banco solo lo usan Tesorería y quien lleve la configuración de Tesorería, con el módulo Banco activo.' => 'El banc només l\'usen Tresoreria i qui porti la configuració de Tresoreria, amb el mòdul Banc actiu.',
	'Ese ingreso ya está revisado o no corresponde a este pedido.' => 'Aquest ingrés ja està revisat o no correspon a aquesta comanda.',
	'Ese pedido o ese movimiento ya no existen.' => 'Aquesta comanda o aquest moviment ja no existeixen.',
	'Ese pedido ya está pagado o cancelado.' => 'Aquesta comanda ja està pagada o cancel·lada.',
	'[%1$s] Pedido cancelado: %2$s' => '[%1$s] Comanda cancel·lada: %2$s',
	'[%1$s] Recordatorio: el pedido %2$s está sin pagar' => '[%1$s] Recordatori: la comanda %2$s està sense pagar',
	'%1$s · generado el %2$s' => '%1$s · generat el %2$s',
	'De ellos, pagado' => 'D\'aquests, pagat',
	'Días esperando' => 'Dies esperant',
	'El ingreso del banco vuelve a estar por conciliar.' => 'L\'ingrés del banc torna a estar per conciliar.',
	'Los informes de ventas los ven Tesorería, Coordinación y la administración de la tienda.' => 'Els informes de vendes els veuen Tresoreria, Coordinació i l\'administració de la botiga.',
	'Pedido %s marcado como pagado con el ingreso del banco.' => 'Comanda %s marcada com a pagada amb l\'ingrés del banc.',
	'Pedidos' => 'Comandes',
	'Pendientes de cobro' => 'Pendents de cobrament',
	'Por cobrar' => 'Per cobrar',
	'Sin indicar' => 'Sense indicar',
	'Todos los pedidos' => 'Totes les comandes',
	'Unidades' => 'Unitats',
	'Ventas por forma de pago' => 'Vendes per forma de pagament',
	'Ventas por producto' => 'Vendes per producte',
	'desde el %s' => 'des del %s',
	'hasta el %s' => 'fins al %s',
	'%d pedido en este periodo.' => '%d comanda en aquest període.',
	'%d pedidos en este periodo.' => '%d comandes en aquest període.',
	'Coincide con el pedido' => 'Coincideix amb la comanda',
	'Con los precios de cada pedido. Lo que está «por confirmar» (precio sin fijar) no suma importe.' => 'Amb els preus de cada comanda. El que està «per confirmar» (preu sense fixar) no suma import.',
	'Confirmar' => 'Confirmar',
	'Días para cancelar un pedido sin pagar (0 = nunca)' => 'Dies per cancel·lar una comanda sense pagar (0 = mai)',
	'Días para recordar el pago (0 = no recordar)' => 'Dies per recordar el pagament (0 = no recordar)',
	'El pedido es de %s' => 'La comanda és de %s',
	'Estos ingresos del banco llevan en el concepto el nº de un pedido que sigue sin pagar. Compruébalos y confirma cada uno: no se marca nada solo.' => 'Aquests ingressos del banc porten al concepte el nº d\'una comanda que continua sense pagar. Comprova\'ls i confirma cadascun: no es marca res sol.',
	'Hasta' => 'Fins a',
	'Ingreso del banco' => 'Ingrés del banc',
	'Ingresos del banco que parecen pagos de pedidos' => 'Ingressos del banc que semblen pagaments de comandes',
	'Lo vendido en la tienda según los pedidos, sin contar los cancelados. Elige el periodo por la fecha en que se hizo el pedido; sin fechas salen todos.' => 'El que s\'ha venut a la botiga segons les comandes, sense comptar les cancel·lades. Tria el període per la data en què es va fer la comanda; sense dates surten totes.',
	'Los pedidos de socios y familias que se hacen en la tienda y no se pagan: se les recuerda por email y, si lo indicas, se cancelan solos y lo que pidieron vuelve a la tienda. Cuenta desde el día del pedido; con 0 no se hace.' => 'Les comandes de socis i famílies que es fan a la botiga i no es paguen: se\'ls ho recorda per email i, si ho indiques, es cancel·len soles i el que van demanar torna a la botiga. Compta des del dia de la comanda; amb 0 no es fa.',
	'Marcar pagado con este ingreso' => 'Marca pagada amb aquest ingrés',
	'No hay pedidos sin pagar en este periodo.' => 'No hi ha comandes sense pagar en aquest període.',
	'No hay ventas en este periodo.' => 'No hi ha vendes en aquest període.',
	'Pedidos de la tienda' => 'Comandes de la botiga',
	'Pedidos sin pagar' => 'Comandes sense pagar',
	'Ventas e informes' => 'Vendes i informes',
	'Volver a la gestión' => 'Torna a la gestió',

