	'Biblioteca de ejemplo' => 'Biblioteca d\'exemples',
	'Cada fila necesita ingrediente, una cantidad mayor que cero y una unidad válida (g, kg, ml, l, ud, cda, pizca).' => 'Cada fila necessita ingredient, una quantitat més gran que zero i una unitat vàlida (g, kg, ml, l, ud, cda, pizca).',
	'Cada ingrediente lleva sus alérgenos; las recetas los heredan. «Puede contener» son las trazas que avisa la etiqueta. Marca «revisado» cuando hayas comprobado la etiqueta: las recetas avisan de los que nadie ha revisado. Los de la biblioteca de ejemplo no se pueden cambiar.' => 'Cada ingredient du els seus al·lèrgens; les receptes els hereten. «Pot contenir» són les traces que avisa l\'etiqueta. Marca «revisat» quan hagis comprovat l\'etiqueta: les receptes avisen dels que ningú no ha revisat. Els de la biblioteca d\'exemples no es poden canviar.',
