	'Es una receta de ejemplo de la biblioteca: no se puede cambiar. Cópiala a tu grupo para editarla.' => 'És una recepta d\'exemple de la biblioteca: no es pot canviar. Copia-la al teu grup per editar-la.',
	'Esa receta es de la biblioteca común: cópiala a tu grupo para editarla.' => 'Aquesta recepta és de la biblioteca comuna: copia-la al teu grup per editar-la.',
	'Escribe el nombre de la receta.' => 'Escriu el nom de la recepta.',
