	'Ingredientes sin revisar' => 'Ingredients sense revisar',
	'Ir a ingredientes' => 'Ves als ingredients',
	'La primera fila tiene que ser la de las columnas: Receta; Tipo; Porciones; Ingrediente; Cantidad; Unidad.' => 'La primera fila ha de ser la de les columnes: Receta; Tipo; Porciones; Ingrediente; Cantidad; Unidad.',
	'La receta «%s» necesita porciones (1 a 500) y al menos un ingrediente válido.' => 'La recepta «%s» necessita porcions (1 a 500) i almenys un ingredient vàlid.',
	'Las porciones base tienen que estar entre 1 y 500.' => 'Les porcions base han d\'estar entre 1 i 500.',
	'Las recetas del grupo, con sus ingredientes. Los alérgenos de cada receta salen de los de sus ingredientes: no se escriben a mano. Aquí no hay datos de ninguna persona.' => 'Les receptes del grup, amb els seus ingredients. Els al·lèrgens de cada recepta surten dels dels seus ingredients: no s\'escriuen a mà. Aquí no hi ha dades de cap persona.',
	'Lista de ingredientes' => 'Llista d\'ingredients',
	'Lleva ingredientes de origen animal (no es apta para dietas vegetarianas ni veganas).' => 'Du ingredients d\'origen animal (no és apta per a dietes vegetarianes ni veganes).',
	'Nadie ha revisado los alérgenos de: %s. Anótalos en «Ingredientes» antes de fiarte de esta lista.' => 'Ningú no ha revisat els al·lèrgens de: %s. Anota\'ls a «Ingredients» abans de refiar-te d\'aquesta llista.',
	'Ninguno anotado' => 'Cap anotat',
