	'Receta nueva' => 'Recepta nova',
	'Recetario' => 'Receptari',
	'Recetas de ejemplo que vienen con la aplicación, iguales para todos los grupos. Copia la que te sirva y edítala: la de la biblioteca no cambia. Comprueba siempre los alérgenos de las marcas que uses antes de fiarte de una receta.' => 'Receptes d\'exemple que vénen amb l\'aplicació, iguals per a tots els grups. Copia la que et serveixi i edita-la: la de la biblioteca no canvia. Comprova sempre els al·lèrgens de les marques que facis servir abans de refiar-te d\'una recepta.',
	'Recetas del grupo' => 'Receptes del grup',
	'Recuperar' => 'Recupera',
	'Si falta un ingrediente, créalo antes en «Ingredientes» con sus alérgenos.' => 'Si falta un ingredient, crea\'l abans a «Ingredients» amb els seus al·lèrgens.',
	'Sin revisar' => 'Sense revisar',
	'Tipo de plato' => 'Tipus de plat',
	'Todavía no hay recetas del grupo. Copia una de la biblioteca de ejemplo, añade una nueva o carga varias desde un CSV.' => 'Encara no hi ha receptes del grup. Copia\'n una de la biblioteca d\'exemples, afegeix-ne una de nova o carrega\'n diverses des d\'un CSV.',
	'Un ingrediente de la lista ya no existe. Elige otro.' => 'Un ingredient de la llista ja no existeix. Tria\'n un altre.',
	'Una fila por cada ingrediente de cada receta, con las columnas: Receta; Tipo; Porciones; Ingrediente; Cantidad; Unidad. Las unidades son g, kg, ml, l, ud, cda y pizca. Los ingredientes que no existan se crean sin alérgenos y sin revisar: anótalos después en «Ingredientes». No se pisa ninguna receta que ya exista.' => 'Una fila per cada ingredient de cada recepta, amb les columnes: Receta; Tipo; Porciones; Ingrediente; Cantidad; Unidad. Les unitats són g, kg, ml, l, ud, cda i pizca. Els ingredients que no existeixin es creen sense al·lèrgens i sense revisar: anota\'ls després a «Ingredients». No es trepitja cap recepta que ja existeixi.',
	'Una receta puede llevar como mucho %d ingredientes.' => 'Una recepta pot dur com a màxim %d ingredients.',
	'Unidad %d' => 'Unitat %d',
