	'Si algo no vuelve, anota la devolución con lo que falta; después puedes descontar esas unidades del inventario. Para pagar una reposición, apúntala en las cuentas del evento.' => 'Si alguna cosa no torna, anota la devolució amb el que falta; després pots descomptar aquestes unitats de l\'inventari. Per pagar una reposició, apunta-la als comptes de l\'esdeveniment.',
