	// v0.56: datos del grupo
	'Cambiar los datos del grupo (nombre, CIF, dirección y provincia)' => 'Canviar les dades del grup (nom, CIF, adreça i província)',
	'El CIF tiene que tener 9 caracteres (letras y números), p. ej. G07123456.' => 'El CIF ha de tenir 9 caràcters (lletres i números), p. ex. G07123456.',
	'El código postal tiene que tener 5 cifras.' => 'El codi postal ha de tenir 5 xifres.',
	'El email de contacto no es válido.' => 'L\'email de contacte no és vàlid.',
	'Elige la provincia de la lista.' => 'Tria la província de la llista.',
	'el CIF' => 'el CIF',
	'la dirección completa (calle, código postal y población)' => 'l\'adreça completa (carrer, codi postal i població)',
	'la provincia (sin ella no se pueden generar números de socio)' => 'la província (sense ella no es poden generar números de soci)',
	'Datos del grupo' => 'Dades del grup',
	'Falta la provincia del grupo (Datos del grupo): sin ella no se pueden generar números de socio.' => 'Falta la província del grup (Dades del grup): sense ella no es poden generar números de soci.',
	'CIF' => 'CIF',
	'Denominación fiscal' => 'Denominació fiscal',
	'Email de contacto' => 'Email de contacte',
	'Es la unión de tres partes: los dos dígitos de la provincia (con su 0 inicial si lo lleva), el nº de grupo y un número incremental de 4 cifras.' => 'És la unió de tres parts: els dos dígits de la província (amb el seu 0 inicial si en porta), el nº de grup i un número incremental de 4 xifres.',
	'Este grupo aún no tiene provincia: sin ella no se pueden reconocer ni generar números de socio/a.' => 'Aquest grup encara no té província: sense ella no es poden reconèixer ni generar números de soci/sòcia.',
	'Falta por rellenar: %s.' => 'Falta per omplir: %s.',
	'G07123456' => 'G07123456',
	'Guardar los datos del grupo' => 'Desar les dades del grup',
	'Lo fija quien administra la web.' => 'El fixa qui administra el web.',
	'Los datos del grupo se escriben una sola vez, aquí: se usan en las domiciliaciones, en los documentos del grupo y para formar el nº de socio/a. Los ve todo el mundo; los cambia el equipo de Coordinación.' => 'Les dades del grup s\'escriuen una sola vegada, aquí: es fan servir en les domiciliacions, en els documents del grup i per formar el nº de soci/sòcia. Les veu tothom; les canvia l\'equip de Coordinació.',
	'Los números que ya existían sin el 0 inicial (p. ej. 76840390) siguen siendo válidos tal cual; los nuevos se generan con la provincia completa.' => 'Els números que ja existien sense el 0 inicial (p. ex. 76840390) continuen sent vàlids tal com són; els nous es generen amb la província completa.',
	'Nº de socio/a del grupo' => 'Nº de soci/sòcia del grup',
	'Provincia %1$s · grupo %2$s · incremental 0001 → %3$s' => 'Província %1$s · grup %2$s · incremental 0001 → %3$s',
	'Si cambio la provincia, entiendo que los números de socio/a del CRM con la provincia anterior dejarán de reconocerse como del grupo (habrá que corregirlos en el CRM). Los usuarios ya creados siguen entrando con su usuario de siempre o con su email.' => 'Si canvio la província, entenc que els números de soci/sòcia del CRM amb la província anterior deixaran de reconèixer-se com del grup (caldrà corregir-los al CRM). Els usuaris ja creats continuen entrant amb el seu usuari de sempre o amb el seu email.',
	'— Elige la provincia —' => '— Tria la província —',
	'Datos del grupo guardados.' => 'Dades del grup desades.',
	'No se ha encontrado el grupo.' => 'No s\'ha trobat el grup.',
